import './notes-toolbar.css';
import { Chip } from './Chip';
import { Field } from './Field';

export function NotesToolbar({ activeFilter = 'all', onFilterChange, searchValue = '', onSearchChange, isPinned = false, onPinChange }) {
  return (
    <div className="notes-toolbar">
      <div className="notes-toolbar__filters">
        <Chip
          Label="All"
          pressed={activeFilter === 'all'}
          onClick={() => onFilterChange?.('all')}
        />
        <Chip
          Label="Mine"
          pressed={activeFilter === 'mine'}
          onClick={() => onFilterChange?.('mine')}
        />
        <Chip
          Label="Shared"
          pressed={activeFilter === 'shared'}
          onClick={() => onFilterChange?.('shared')}
        />
      </div>
      <Field
        label="Search notes"
        placeholder="Search..."
        value={searchValue}
        onChange={(e) => onSearchChange?.(e.target.value)}
      />
      <Chip
        Icon
        pressed={isPinned}
        onClick={() => onPinChange?.(!isPinned)}
        aria-label="Pin note"
        className="notes-toolbar__pin-chip"
      />
    </div>
  );
}

