import { Chip } from './Chip';
import { Field } from './Field';
import './notesToolbar.css';

export function NotesToolbar({ onFilterChange, onSearchChange, onPinToggle, pinned = false }) {
  const handleFilterClick = (filter) => {
    onFilterChange?.(filter);
  };

  return (
    <div className="notes-toolbar">
      <div className="notes-toolbar__filters">
        <Chip Label="All" pressed={false} onClick={() => handleFilterClick('all')} />
        <Chip Label="Mine" pressed={false} onClick={() => handleFilterClick('mine')} />
        <Chip Label="Shared" pressed={false} onClick={() => handleFilterClick('shared')} />
      </div>
      <div className="notes-toolbar__search">
        <Field
          label="Search notes"
          placeholder="Search notes..."
          onChange={(e) => onSearchChange?.(e.target.value)}
        />
      </div>
      <button
        className={`notes-toolbar__pin${pinned ? ' notes-toolbar__pin--active' : ''}`}
        aria-label={pinned ? 'Unpin notes' : 'Pin notes'}
        aria-pressed={pinned}
        onClick={() => onPinToggle?.(!pinned)}
      >
        <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
          <path d="M16 3H5c-1.11 0-2 .9-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V8l-5-5zm-3 14h-2v-4h-4v-2h4V9h2v2h4v2h-4v4z"/>
        </svg>
      </button>
    </div>
  );
}

