.notes-toolbar__filters {
  display: flex;
  gap: var(--gap-s);
}

.notes-toolbar__search {
  flex: 1;
}

.notes-toolbar__pin {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: var(--radii-chip);
  background-color: var(--chip-background);
  color: var(--chip-text);
  cursor: pointer;
  transition: background-color 150ms ease;
}

.notes-toolbar__pin:hover {
  background-color: var(--chip-background);
  opacity: 0.8;
}

.notes-toolbar__pin--active {
  background-color: var(--button-background);
  color: var(--button-text);
}

.notes-toolbar__pin--active:hover {
  background-color: var(--button-background-hover);
}
